:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --text-muted: #a0a0b0;
  --focus: #e94560;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 32px 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  font-size: 1.75rem;
  text-align: center;
  color: var(--accent);
  letter-spacing: 1px;
}

.output-box {
  background: var(--bg);
  border: 2px solid var(--primary);
  border-radius: 8px;
  padding: 16px;
  font-family: 'Courier New', monospace;
  font-size: 1.125rem;
  text-align: center;
  word-break: break-all;
  min-height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  transition: border-color 0.2s;
}

.output-box:not(:empty) {
  color: var(--text);
}

.strength-label {
  text-align: center;
  font-size: 1rem;
  font-weight: 600;
  padding: 8px;
  border-radius: 8px;
  background: var(--primary);
  color: var(--text-muted);
  transition: background 0.3s, color 0.3s;
}

.strength-label.weak { background: #e94560; color: #fff; }
.strength-label.medium { background: #f5a623; color: #1a1a2e; }
.strength-label.strong { background: #2ecc71; color: #1a1a2e; }

.control-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.control-group label {
  font-size: 1rem;
  font-weight: 500;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

#lengthValue {
  font-weight: 700;
  color: var(--accent);
  font-size: 1.125rem;
}

input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 8px;
  background: var(--primary);
  border-radius: 4px;
  outline: none;
  cursor: pointer;
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent);
  cursor: pointer;
  transition: transform 0.15s;
}

input[type="range"]::-moz-range-thumb {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent);
  border: none;
  cursor: pointer;
}

input[type="range"]:hover::-webkit-slider-thumb { transform: scale(1.15); }
input[type="range"]:focus-visible { box-shadow: 0 0 0 3px var(--focus); }

.toggles {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.toggle {
  display: flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  padding: 4px 0;
  position: relative;
}

.toggle input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.toggle-track {
  width: 48px;
  height: 28px;
  background: var(--primary);
  border-radius: 14px;
  position: relative;
  transition: background 0.2s;
  flex-shrink: 0;
}

.toggle-track::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  background: var(--text-muted);
  border-radius: 50%;
  transition: transform 0.2s, background 0.2s;
}

.toggle input:checked + .toggle-track {
  background: var(--accent);
}

.toggle input:checked + .toggle-track::after {
  transform: translateX(20px);
  background: #fff;
}

.toggle input:focus-visible + .toggle-track {
  box-shadow: 0 0 0 3px var(--focus);
}

.toggle:hover .toggle-track {
  filter: brightness(1.2);
}

.toggle-text {
  font-size: 1rem;
  user-select: none;
}

.generate-btn {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 12px;
  padding: 16px;
  font-size: 1.125rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  letter-spacing: 0.5px;
}

.generate-btn:hover {
  background: #f05a72;
}

.generate-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.generate-btn:active {
  transform: scale(0.97);
  background: #d13a54;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .output-box {
    font-size: 1rem;
  }
}

(function () {
  'use strict';

  const lengthSlider = document.getElementById('lengthSlider');
  const lengthValue = document.getElementById('lengthValue');
  const uppercaseToggle = document.getElementById('uppercaseToggle');
  const numbersToggle = document.getElementById('numbersToggle');
  const symbolsToggle = document.getElementById('symbolsToggle');
  const generateBtn = document.getElementById('generateBtn');
  const passwordDisplay = document.getElementById('passwordDisplay');
  const strengthLabel = document.getElementById('strengthLabel');

  const LOWERCASE = 'abcdefghijklmnopqrstuvwxyz';
  const UPPERCASE = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const NUMBERS = '0123456789';
  const SYMBOLS = '!@#$%^&*()_+-=[]{}|;:,.<>?';

  function updateLengthDisplay() {
    const val = lengthSlider.value;
    lengthValue.textContent = val;
    lengthSlider.setAttribute('aria-valuenow', val);
  }

  function getCharPool() {
    let pool = LOWERCASE;
    if (uppercaseToggle.checked) pool += UPPERCASE;
    if (numbersToggle.checked) pool += NUMBERS;
    if (symbolsToggle.checked) pool += SYMBOLS;
    return pool;
  }

  function secureRandom(max) {
    if (window.crypto && window.crypto.getRandomValues) {
      const array = new Uint32Array(1);
      window.crypto.getRandomValues(array);
      return array[0] % max;
    }
    return Math.floor(Math.random() * max);
  }

  function generatePassword() {
    const length = parseInt(lengthSlider.value, 10);
    const pool = getCharPool();
    let password = '';
    for (let i = 0; i < length; i++) {
      password += pool[secureRandom(pool.length)];
    }
    return password;
  }

  function calculateStrength(password) {
    let variety = 0;
    if (/[a-z]/.test(password)) variety++;
    if (/[A-Z]/.test(password)) variety++;
    if (/[0-9]/.test(password)) variety++;
    if (/[^a-zA-Z0-9]/.test(password)) variety++;

    const length = password.length;
    let score = 0;
    if (length >= 8) score++;
    if (length >= 12) score++;
    if (length >= 16) score++;
    if (length >= 24) score++;
    score += variety;

    if (score <= 3) return 'weak';
    if (score <= 5) return 'medium';
    return 'strong';
  }

  function updateStrength(password) {
    const strength = calculateStrength(password);
    strengthLabel.className = 'strength-label ' + strength;
    const labels = { weak: 'Weak', medium: 'Medium', strong: 'Strong' };
    strengthLabel.textContent = 'Strength: ' + labels[strength];
  }

  function handleGenerate() {
    const password = generatePassword();
    passwordDisplay.textContent = password;
    updateStrength(password);
  }

  lengthSlider.addEventListener('input', updateLengthDisplay);
  generateBtn.addEventListener('click', handleGenerate);

  updateLengthDisplay();
})();
